@startuml

class City {
  + Name : string
}

class H2SLocation {
  + LocationID : string
}

class Resident {
  + Name : string
  + StreetAddress : string
  + PhoneNumber : string
  + Email : string
  + ItemDescription : string
}

class PickupRequest {
  + RequestedDate : date
  + PickupTimeWindow : string
}

class Vehicle {
  + LicensePlate : string
  + StorageCapacity : float
}

class VolunteerDriver {
  + Name : string
  + AvailableDays : string[]
}

class PickupRoute {
  + RouteDate : date
}

class Article {
  + Description : string
  + Category : string
  + RFIDTag : string
  + IsUsable : boolean
}

class DistributionCenter {
  + Address : string
}

class Employee {
  + EmployeeID : string
  + Name : string
}

class Client {
  + Name : string
  + HomeAddress : string
  + NeededCategories : string[]
}

class FoodBank {
  + Address : string
}

H2SLocation "1" -- "1" City
H2SLocation "1" *-- "1" DistributionCenter
DistributionCenter "1" -- "1..*" Article : processes
DistributionCenter "1" -- "1..*" Client : serves

Resident "1" -- "0..*" PickupRequest : schedules
PickupRequest "1" -- "1..*" Article : contains

Vehicle "1" -- "0..*" PickupRoute : assignedTo
VolunteerDriver "1" -- "0..*" PickupRoute : drives
PickupRoute "1" -- "1..*" PickupRequest : includes

Article "1" -- "1" Category
Employee "1" -- "0..*" Article : inspects
Employee "1" -- "0..*" Client : calls

Article "1" -- "1" FoodBank : deliveredTo
Article "1" -- "1" DistributionCenter : storedAt

@enduml

